package com.maris7.team.command;
import com.maris7.team.MarisTeam;import com.maris7.team.model.Team;import com.maris7.team.util.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class TeamAdminCommand implements CommandExecutor,TabCompleter{private final MarisTeam p;private final Msg msg;public TeamAdminCommand(MarisTeam p){this.p=p;this.msg=new Msg(p);} public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!s.hasPermission("maristeam.admin")){if(s instanceof Player pl)msg.both(pl,"no-permission","no");return true;} if(a.length>0&&a[0].equalsIgnoreCase("reload")){p.reloadAll(); if(s instanceof Player pl)msg.both(pl,"reloaded",null); else s.sendMessage("MarisTeam reloaded");return true;} if(a.length>1&&a[0].equalsIgnoreCase("delete")){Team t=p.teams().byName(a[1]); if(t!=null){String admin=s.getName(); p.teams().disband(t,Text.color(p.configs().messages().getString("disbanded-by-admin").replace("%admin%",admin))); if(s instanceof Player pl)msg.both(pl,"admin-deleted","success",Map.of("%team%",t.name)); else s.sendMessage("Deleted team: "+t.name);}else s.sendMessage("Team not found: "+a[1]);return true;} return true;} public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){return a.length==1?List.of("delete","reload"):List.of();}}
